  string PlatformCategory(RoutePlan p){var s=(researchState.sources??new List<ResearchSource>()).FirstOrDefault(x=>x.id==p.id);return p.id=="epic"?"游戏与引擎":s==null?"科研来源":s.category;}
  void ShowPicker(bool show){N<Border>("CatalogPanel").Visibility=show?Visibility.Visible:Visibility.Collapsed;N<StackPanel>("RoutingDetails").Visibility=show?Visibility.Collapsed:Visibility.Visible;N<Button>("ChangePlatform").Visibility=show?Visibility.Collapsed:Visibility.Visible;N<TextBlock>("CatalogSelection").Text=routePlan==null?"请选择平台":"当前选择："+routePlan.name;N<ScrollViewer>("RoutingScroll").ScrollToTop();}
  void UpdatePlatformHealth(){foreach(var pair in routeHealth){var h=(researchState.health??new List<SourceHealth>()).FirstOrDefault(x=>x.id==pair.Key);pair.Value.Text=pair.Key=="epic"?"UE / 游戏 CDN":h==null?"未检测":h.status;TextBlock label;if(catalogHealth.TryGetValue(pair.Key,out label))label.Text=pair.Value.Text;}FilterPlatforms();}
  void FilterPlatforms(){if(routeState==null)return;string query=N<TextBox>("PlatformSearch").Text.Trim();string category=N<ComboBox>("CatalogCategory").SelectedItem as string;string nextFilter=query+"|"+category;if(nextFilter!=catalogFilter){catalogFilter=nextFilter;window.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,new Action(()=>N<ScrollViewer>("CatalogScroll").ScrollToTop()));}int visible=0;foreach(var p in routeState.plans){Button b;if(!routeCards.TryGetValue(p.id,out b))continue;bool match=query.Length==0||(p.name+PlatformCategory(p)+String.Join(" ",p.hosts)+routeHealth[p.id].Text).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0;b.Visibility=match?Visibility.Visible:Visibility.Collapsed;Button card;if(catalogCards.TryGetValue(p.id,out card))card.Visibility=match&&(String.IsNullOrEmpty(category)||category=="全部分类"||category==PlatformCategory(p))?Visibility.Visible:Visibility.Collapsed;if(card!=null&&card.Visibility==Visibility.Visible)visible++;}foreach(var label in categoryLabels)label.Visibility=((string[])label.Tag).Any(id=>routeCards[id].Visibility==Visibility.Visible)?Visibility.Visible:Visibility.Collapsed;N<TextBlock>("PlatformCount").Text=routeCards.Count+" 个来源 · 可搜索";N<TextBlock>("CatalogCount").Text=visible+" / "+routeCards.Count+" 个来源";}
  void SelectRoute(RoutePlan plan,string host){routePlan=plan;ShowPage("routing");ShowPicker(false);N<Border>("RoutingHeroIcon").Background=Hex(plan.id=="pypi"||plan.id=="zenodo"?"#496CAD":"#FFFFFF");N<Border>("RoutingHeroIcon").Child=PlatformIcon(plan.id,plan.mark,42);N<TextBlock>("RoutingTitle").Text=plan.name;N<TextBlock>("RoutingService").Text=plan.service;N<TextBlock>("RoutingScope").Text=plan.note;var choices=new List<RouteChoice>{new RouteChoice{Label=plan.service+"（全部已接入域名）",Host=""}};if(plan.hosts.Length>1)choices.AddRange(plan.hosts.Select(h=>new RouteChoice{Label="仅 "+h,Host=h}));N<ComboBox>("RoutingChoice").ItemsSource=choices;N<ComboBox>("RoutingChoice").SelectedItem=choices.FirstOrDefault(c=>c.Host==host)??choices.First();UpdateRoutingView();}
  void SaveRouteChoice(){var choice=N<ComboBox>("RoutingChoice").SelectedItem as RouteChoice;if(routePlan==null||choice==null)return;try{Directory.CreateDirectory(Path.GetDirectoryName(RoutePreferencePath));File.WriteAllText(RoutePreferencePath,json.Serialize(new SavedRoute{id=routePlan.id,host=choice.Host}),Encoding.UTF8);}catch(Exception e){Log("选择未能保存："+e.Message);}}
