   foreach(var c in routeCards){c.Value.SetResourceReference(Button.BackgroundProperty,c.Key==routePlan.id&&currentPage=="routing"?"Soft":"Panel");c.Value.SetResourceReference(Button.BorderBrushProperty,c.Key==routePlan.id&&currentPage=="routing"?"Accent":"Line");c.Value.IsEnabled=!busy;}foreach(var c in catalogCards){c.Value.SetResourceReference(Button.BackgroundProperty,c.Key==routePlan.id?"Soft":"Panel");c.Value.SetResourceReference(Button.BorderBrushProperty,c.Key==routePlan.id?"Accent":"Line");c.Value.IsEnabled=!busy;} UpdateNodeControls();
